dir:

































  &DefaultButton;




function dir$dmkien(p){
  this.constructor(p);
}
dir$dmkien.prototype = new DirEvent();
dir$dmkien.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmkien.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

  dir$dmkienDisabledMasterField(p, g);

}

function dir$dmkienDisabledMasterField(p, g){

  if(p.valForm('ma_kien').trim() != '')
  {
    p.setDisabled('ma_kien', true);
  }
  else
  {
    p.setDisabled('ma_kien', false);
  }
}








declare @codeExistsNewMsg nvarchar(256), @codeExistsEditMsg nvarchar(256)
select @codeExistsNewMsg = case when '@@lan' = 'v' then N'Mã kiện đã tồn tại' else N'The parcel code already exists' end
select @codeExistsEditMsg = case when '@@lan' = 'v' then N'Mã kiện đã tồn tại' else N'The parcel code already exists' end
